// ---------------------------------------------------------------------------
// sections.generated.ts — generated by nvoos-astro-forge (Proposal 117 §2);
// edits are overwritten on re-scaffold. The source band theming: each entry
// keys the source Elementor section id to its background facts and the
// resolved rebuild theme. The DesignRenderer matches rebuilt sections by id
// and wraps them accordingly. Deterministic: same profile, same bytes.
// ---------------------------------------------------------------------------

export type SectionThemeName = 'hero' | 'dark' | 'alt' | 'light';

export interface SectionTheme {
	id?: string;
	theme: SectionThemeName;
	/** The source section anchor (the chrome nav links to it). */
	anchor?: string;
	/** The source band background (gradient or flat color). */
	bg?: string;
	/** The hero photo (hero sections only). */
	bgImage?: string;
	/** The overlay tint over the hero photo. */
	overlay?: string;
	/** The source band padding (the declared padding fact). */
	padding?: string;
	/** The boxed container width (the source constrains its content —
	 * jayainc's Elementor 1140px default). Absent → the site measure. */
	measure?: string;
	/** The container column-gap gutter (gap-default 10px … wider 30px). */
	paddingX?: string;
	/** Section-level pull facts (124 §4) — negative margins overlap
	 * the neighbor band; z-index stacks the overlap. */
	marginTop?: string;
	marginBottom?: string;
	zIndex?: string;
	/** The top-level column responsive facts (124 §6) — widths per
	 * device + order/visibility; the split components re-measure. */
	columns?: Array<{
		width?: number;
		widthTablet?: number;
		widthMobile?: number;
		reverseMobile?: boolean;
		reverseTablet?: boolean;
		hiddenMobile?: boolean;
		hiddenTablet?: boolean;
		hiddenDesktop?: boolean;
	}>;
}

export const sections: SectionTheme[] = [];
